def first_bad_version(n, is_bad_version):
    lo, hi = 1, n
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if is_bad_version(mid):
            hi = mid                    # bad at or before mid, search left (inclusive)
        else:
            lo = mid + 1                 # good, search strictly right
    return lo

